#[test]
fn stage_cameras_match_reference() {
    let Some((fx, arcs)) = env("stage_cameras_match_reference", "stage_cameras.json") else {
        return;
    };
    let cams = fx.as_array().unwrap();
    assert_eq!(cams.len(), 93);
    let arc =
        ArcFile::open(&arcs.join("camera").join("stage_camera.arc")).expect("stage_camera.arc");
    for cam in cams {
        let path = cam["path"].as_str().unwrap();
        let bytes = arc.get(path).unwrap_or_else(|| panic!("missing {path}"));
        let a = parse(&bytes).unwrap_or_else(|e| panic!("{path}: {e}"));
        assert!(a.has_camera(), "{path}");
        assert!(a.bone_tracks.is_empty());
        assert_eq!(a.frame_count as i64, i(&cam["frame_count"]));
        assert_eq!(a.fps, f(&cam["fps"]), "{path} fps");
        assert_eq!(a.loops, cam["loops"].as_bool().unwrap());
        let kinds = cam["slot_kinds"].as_array().unwrap();
        for (slot, k) in kinds.iter().enumerate() {
            match (&a.camera_slots[slot], k.as_i64()) {
                (None, None) => {}
                (Some(t), Some(kind)) => assert_eq!(t.kind as i64, kind, "{path} slot {slot}"),
                (got, exp) => panic!("{path} slot {slot}: {got:?} vs {exp:?}"),
            }
        }
        let frames = farr(&cam["frames"]);
        let rows = cam["slots"].as_array().unwrap();
        for (fi, frame) in frames.iter().enumerate() {
            let s = sample_slots(&a, &bytes, *frame);
            let row = rows[fi].as_array().unwrap();
            for slot in 0..6 {
                if row[slot].is_null() {
                    assert!(!s.present[slot]);
                    continue;
                }
                assert!(s.present[slot], "{path} slot {slot} present");
                match slot {
                    0 => assert!(
                        quat_close(&s.q, &farr(&row[0]), SAMPLE_TOL),
                        "{path} f{frame} q {:?} vs {:?}",
                        s.q,
                        row[0]
                    ),
                    1 => {
                        let e = farr(&row[1]);
                        // centimetres up to ~2500: f32 ulp there is ~2.4e-4
                        assert!(
                            s.pos_cm.iter().zip(&e).all(|(x, y)| close(
                                *x,
                                *y,
                                1e-4 + 1e-6 * y.abs()
                            )),
                            "{path} f{frame} pos {:?} vs {e:?}",
                            s.pos_cm
                        );
                    }
                    2 => assert!(close(s.fov_v_deg, f(&row[2]), 1e-4)),
                    3 => assert!(close(s.near, f(&row[3]), 1e-6)),
                    4 => assert!(
                        close(s.far, f(&row[4]), 1e-1),
                        "{path} far {} vs {}",
                        s.far,
                        row[4]
                    ),
                    _ => assert!(close(s.aspect_file, f(&row[5]), 1e-5)),
                }
            }
            // the recipe's algebra over the sampled slots
            let c = camera_from_slots(&s, 1.0, 1.0);
            for k in 0..3 {
                assert!(close(c.eye[k], s.pos_cm[k] * 0.01, 1e-5));
            }
            let d = [
                c.target[0] - c.eye[0],
                c.target[1] - c.eye[1],
                c.target[2] - c.eye[2],
            ];
            assert!(
                close((d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt(), 10.0, 1e-3),
                "{path} target distance"
            );
            assert!(close(
                (c.up[0] * c.up[0] + c.up[1] * c.up[1] + c.up[2] * c.up[2]).sqrt(),
                1.0,
                1e-5
            ));
            assert_eq!(c.l, -c.r);
            assert_eq!(c.b, -c.t);
            assert!(close(c.r / c.t, 16.0 / 9.0, 1e-4));
            assert!(c.r > 0.0 && c.r < 2.0, "{path} half-tangent {}", c.r);
            assert_eq!(c.near, s.near);
            assert_eq!(c.far, s.far);
        }
    }
    eprintln!("stage cameras: {} camanms compared", cams.len());
}

