#[test]
fn rlists_match_reference() {
    let Some((fx, arcs)) = env("rlists_match_reference", "rlists.json") else {
        return;
    };
    let arc = ArcFile::open(&arcs.join("startup.arc")).expect("startup.arc");
    let obj = fx.as_object().unwrap();
    assert_eq!(obj.len(), 4);
    for (path, rows_exp) in obj {
        let bytes = arc.get(path).unwrap_or_else(|| panic!("missing {path}"));
        let rows = rlist::parse(&bytes).unwrap_or_else(|e| panic!("{path}: {e}"));
        let exp = rows_exp.as_array().unwrap();
        assert_eq!(rows.len(), exp.len(), "{path} row count");
        for (r, e) in rows.iter().zip(exp) {
            let e = e.as_array().unwrap();
            assert_eq!(r.0, e[0].as_str().unwrap(), "{path} key");
            let fields: Vec<&str> = e[1]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap())
                .collect();
            assert_eq!(r.1, fields, "{path} fields of {}", r.0);
        }
    }
    // the rows the design leans on
    let chara = rlist::parse(&arc.get("data/chara/chara_resources.rlist").unwrap()).unwrap();
    assert_eq!(chara.len(), 26);
    let (row, (_, fields)) = rlist::find(&chara, "emi00").unwrap();
    assert_eq!(row, 21);
    assert_eq!(fields[..3], ["pl", "F", "A"].map(String::from));
    let map = rlist::parse(&arc.get("data/map/map_resources.rlist").unwrap()).unwrap();
    assert_eq!(map.len(), 34);
    assert_eq!(map[0].0, "boom00");
    assert_eq!(map[32].0, "boom00");
    assert!(map[32].1.iter().any(|f| f == "footpanel"));
    assert_eq!(map.iter().filter(|(k, _)| k == "dummy00").count(), 7);
}

#[test]
fn pl_emi00_b2it_and_bone_table_match_reference() {
    let Some((fx, arcs)) = env(
        "pl_emi00_b2it_and_bone_table_match_reference",
        "pl_emi00.json",
    ) else {
        return;
    };
    let arc = ArcFile::open(&arcs.join("pl_emi00.arc")).expect("pl_emi00.arc");
    let b2 = b2it::parse(&arc.get("data/chara/pl_emi00/pl_emi00.b2it").unwrap()).unwrap();
    let exp = fx["b2it"].as_array().unwrap();
    assert_eq!(b2.len(), exp.len());
    assert_eq!(b2.len(), 33);
    for (got, e) in b2.iter().zip(exp) {
        let e = e.as_array().unwrap();
        assert_eq!(got.0, e[0].as_str().unwrap());
        assert_eq!(got.1 as i64, i(&e[1]));
    }
    // sorted ordinally → binary search works on the file order
    assert!(b2.windows(2).all(|w| w[0].0.as_bytes() < w[1].0.as_bytes()));
    assert_eq!(b2it::index_of(&b2, "Head"), Some(16));
    assert_eq!(b2it::index_of(&b2, "Hips"), Some(1));
    assert_eq!(b2it::index_of(&b2, "Spine2"), Some(8));
    assert_eq!(b2it::index_of(&b2, "LeftForeArmRoll"), Some(29));
    assert_eq!(b2it::index_of(&b2, "RightForeArmRoll"), Some(30));
    assert_eq!(b2it::index_of(&b2, "nope"), None);

    let model = arc.get("data/chara/pl_emi00/pl_emi00.model").unwrap();
    let sk = ktmdl::bone_table(&model).unwrap();
    let bones = &fx["bones"];
    let parents: Vec<i16> = bones["parents"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| i(p) as i16)
        .collect();
    assert_eq!(sk.parents, parents);
    assert_eq!(sk.bone_count(), 33);
    let bind = bones["bind"].as_array().unwrap();
    let inverse = bones["inverse"].as_array().unwrap();
    for b in 0..33 {
        let eb = farr(&bind[b]);
        let ei = farr(&inverse[b]);
        for k in 0..16 {
            assert!(close(sk.bind_world[b][k], eb[k], 1e-6), "bind {b}[{k}]");
            assert!(
                close(sk.inverse_bind[b][k], ei[k], 1e-6),
                "inverse {b}[{k}]"
            );
        }
        // bind · inverse ≈ I
        let p = mat_mul(&sk.bind_world[b], &sk.inverse_bind[b]);
        for k in 0..16 {
            assert!(
                close(p[k], MAT4_IDENTITY[k], 1e-4),
                "bind·inv {b}[{k}] = {}",
                p[k]
            );
        }
        // topological order
        assert!(sk.parents[b] < b as i16);
    }
    // Hips at y ≈ 0.97 m (docs §3.2)
    assert!(
        close(sk.bind_world[1][13], 0.97, 0.05),
        "hips y {}",
        sk.bind_world[1][13]
    );

    // The A3 seed reproduces the real rig's bind pose with no tracks.
    let seed = seed_local_trs(&sk);
    let empty = super::build_anm(1, 0, 1, false, &[], None);
    let a = parse(&empty).unwrap();
    let world: Vec<Mat4> = evaluate(&a, &empty, 0.0, &sk, &seed);
    for b in 0..33 {
        for k in 0..16 {
            assert!(
                close(world[b][k], sk.bind_world[b][k], 1e-4),
                "seeded world {b}[{k}]: {} vs {}",
                world[b][k],
                sk.bind_world[b][k]
            );
        }
    }
}
